    static func maxError(_ a: [Float], _ b: [Float]) -> Float {
        zip(a, b).map { abs($0 - $1) }.max() ?? .infinity
    }

    @Test("Forward transform matches Demucs")
    func forward() {
        let transform = KaraokeDemucsSpectrogram(layout: Self.tiny)
        let out = transform.forward(left: Array(Self.input[0..<37]), right: Array(Self.input[37...]))
        #expect(out.count == Self.spectrum.count)
        #expect(Self.maxError(out, Self.spectrum) < 1e-5)
    }

    @Test("Inverse transform matches Demucs")
    func inverse() {
        let transform = KaraokeDemucsSpectrogram(layout: Self.tiny)
        let (left, right) = transform.inverse(spectrum: Self.modelSpectrum, length: 37)
        #expect(Self.maxError(left + right, Self.modelWave) < 1e-5)
    }

    @Test("Segments and stitching match apply_model")
    func stitching() {
        let left = Array(Self.mix[0..<131]), right = Array(Self.mix[131...])
        let plan = KaraokeSeparationPlan(totalLength: 131, layout: Self.tiny)
        #expect(plan.segments.map(\.offset) == [0, 45, 90])
        var accumulator = KaraokeSeparationAccumulator(plan: plan)
        for segment in plan.segments {
            let mock: ([Float]) -> [Float] = { window in
                window.enumerated().map { 0.5 * $0.element + Float($0.offset) / 100 }
            }
            accumulator.add(
                segment,
                left: mock(plan.window(segment, of: left)),
                right: mock(plan.window(segment, of: right))
            )
        }
        let (l, r) = accumulator.finish()
        #expect(Self.maxError(l + r, Self.stitched) < 1e-5)
    }

    @Test("Standard layout sizes match the converted model")
    func standardLayout() {
        let layout = KaraokeDemucsLayout.standard
        #expect(layout.bins == 2_048)
        #expect(layout.frames(forLength: layout.segmentLength) == 336)
        let plan = KaraokeSeparationPlan(totalLength: 44_100 * 240)
        #expect(plan.segments.count == 42)
        #expect(plan.segments.last.map { $0.offset + $0.length } == 44_100 * 240)
    }
}
